package cz.mh.rallye.rallye_backend.participation.application;

import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import java.math.BigInteger;
import org.springframework.stereotype.Service;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;
import cz.mh.rallye.rallye_backend.identity.application.*;import cz.mh.rallye.rallye_backend.identity.application.AuthService.Principal;
import cz.mh.rallye.rallye_backend.identity.persistence.*;import cz.mh.rallye.rallye_backend.crews.persistence.CrewStore;
import cz.mh.rallye.rallye_backend.races.application.LifecycleService;import cz.mh.rallye.rallye_backend.races.domain.EventLifecycle;import cz.mh.rallye.rallye_backend.races.persistence.EventStore;
import cz.mh.rallye.rallye_backend.participation.persistence.*;import cz.mh.rallye.rallye_backend.participation.persistence.CrewStartStore.*;
import cz.mh.rallye.rallye_backend.competition.domain.RaceEvaluator;
import cz.mh.rallye.rallye_backend.shared.persistence.CommandStore;import cz.mh.rallye.rallye_backend.audit.application.AuditService;

/** Account-authenticated start/control; independent device authorization is RaceDeviceAccess. No gameplay. */
@Service
public class CrewStartService {
 public record RedemptionReceipt(UUID registrationId,long registrationVersion,UUID codeId,String kind,String effect,Instant individualStartedAt,UUID runId,long activationGeneration,long runVersion,UUID deviceId,long deviceGeneration,String pointsAdjustment){}
 public record RevocationReceipt(UUID revocationId,UUID registrationId,long registrationVersion,UUID deviceId,long revokedDeviceGeneration,long deviceGeneration,String state,Instant revokedAt,UUID currentRunId){}
 public record ActiveDevice(UUID id,long generation,Instant createdAt,String label){}
 public record StartStatus(UUID registrationId,long registrationVersion,Instant serverTime,String eventStatus,Instant individualStartedAt,boolean canStart,String blockedReason,UUID currentRunId,boolean canTakeOver,String takeOverBlockedReason,long deviceGeneration,ActiveDevice activeDevice){}
 private record Locked(EventStore.Event event,Registration registration){}
 private record Planned(Code code,Run run){}
 private final CrewStartStore store;private final RegistrationStore registrations;private final CrewStore crews;private final AccountStore accounts;private final AdminStore roles;private final CommandStore ledger;private final AuditService audit;private final CrewStartSecrets secrets;private final SecretTokens hashes;private final CrewStartAttempts attempts;private final EventStore events;private final LifecycleService lifecycle;private final Clock clock;private final TransactionTemplate tx;
 private final RaceEvaluator evaluator=new RaceEvaluator();private static final JsonMapper JSON=JsonMapper.builder().build();
 public CrewStartService(CrewStartStore store,RegistrationStore registrations,CrewStore crews,AccountStore accounts,AdminStore roles,CommandStore ledger,AuditService audit,CrewStartSecrets secrets,SecretTokens hashes,CrewStartAttempts attempts,EventStore events,LifecycleService lifecycle,Clock clock,PlatformTransactionManager manager){this.store=store;this.registrations=registrations;this.crews=crews;this.accounts=accounts;this.roles=roles;this.ledger=ledger;this.audit=audit;this.secrets=secrets;this.hashes=hashes;this.attempts=attempts;this.events=events;this.lifecycle=lifecycle;this.clock=clock;tx=new TransactionTemplate(manager);}
 private Instant now(){return clock.instant().truncatedTo(ChronoUnit.MILLIS);}
 private static AuthFailure error(int status,String code){return new AuthFailure(status,code);}
 private void authorize(Principal p,boolean admin,boolean lock){if(p==null)throw AuthFailure.credentials();if(lock){roles.lock();accounts.lockAccount(p.accountId());}if(!roles.activeVerified(p.accountId())||!accounts.isActiveSession(p.sessionId(),p.accountId(),now()))throw AuthFailure.credentials();if(admin&&!roles.administrator(p.accountId()))throw error(403,"ADMIN_REQUIRED");}
 private Locked lock(Principal p,UUID event,UUID registration,boolean admin){authorize(p,admin,true);UUID crew=registrations.crew(event,registration);var c=crew==null?null:crews.find(crew);if(!admin&&(c==null||!p.accountId().equals(c.captainAccountId())))throw error(404,"REGISTRATION_NOT_FOUND");var e=events.lock(event);if(e==null)throw error(404,"RACE_EVENT_NOT_FOUND");var r=store.registration(registration,true);if(crew==null||r==null||!r.eventId().equals(event))throw error(404,"REGISTRATION_NOT_FOUND");return new Locked(e,r);}
 private static void version(long expected,Registration r){if(expected!=r.version())throw error(409,"REGISTRATION_VERSION_CONFLICT");}
 private static String text(String raw,int maximum){if(raw==null)return null;if(raw.indexOf(0)>=0||raw.codePointCount(0,raw.length())>maximum)throw error(400,"INVALID_REQUEST");return raw.isBlank()?null:raw.strip();}
 private String fingerprint(Object... fields){return hashes.hash(JSON.writeValueAsString(Arrays.asList(fields)));}
 private static String request(UUID event,UUID registration,String fingerprint){return JSON.writeValueAsString(List.of(event,registration,fingerprint));}
 private Command previous(Principal p,UUID key,String operation,UUID event,UUID registration,String fingerprint,Instant at){String shared="RACE_"+operation;String oldShared=ledger.replay(p.accountId(),key,shared,request(event,registration,fingerprint),at);var old=store.command(p.accountId(),key);if(old==null){if(oldShared!=null)throw error(503,"RACE_STATE_UNAVAILABLE");return null;}if(!old.operation().equals(operation)||!old.registrationId().equals(registration)||old.fingerprintVersion()!=1||!old.fingerprint().equals(fingerprint))throw error(409,"IDEMPOTENCY_CONFLICT");if(oldShared!=null&&!JSON.readTree(oldShared).get("commandId").asString().equals(old.id().toString()))throw error(503,"RACE_STATE_UNAVAILABLE");return old;}
 private void evidence(Principal p,UUID key,UUID event,UUID registration,String operation,String fingerprint,UUID code,UUID device,UUID command,Instant at,Object receipt){store.insertCommand(new Command(command,registration,p.accountId(),key,operation,1,fingerprint,code,null,device,at,200,JSON.writeValueAsString(receipt)));ledger.save(p.accountId(),key,registration,"RACE_"+operation,request(event,registration,fingerprint),JSON.writeValueAsString(Map.of("commandId",command)),at);}
 public RedemptionReceipt redeem(Principal p,UUID event,UUID registration,UUID key,long expected,String rawCode,String rawSecret,String rawLabel){
  attempts.account(p==null?null:p.accountId());if(key==null||expected<0)throw error(400,"INVALID_REQUEST");String codeValue=secrets.normalizeCode(rawCode);var hash=secrets.deviceHash(rawSecret);String label=text(rawLabel,100);
  try{LifecycleService.Outcome<RedemptionReceipt> outcome=tx.execute(s->{var locked=lock(p,event,registration,false);var r=locked.registration();Instant at=now();
   // A durable replay knows the code UUID even after consumption. Short code comparison is direct.
   Command hint=store.command(p.accountId(),key);
   if(hint!=null){if(!hint.operation().equals("CODE_REDEEM")||!hint.registrationId().equals(registration))throw error(409,"IDEMPOTENCY_CONFLICT");var c=store.code(registration,hint.codeId(),false);var d=store.device(registration,hint.deviceId(),false);if(c==null||d==null)throw error(503,"RACE_STATE_UNAVAILABLE");if(!c.value().equals(codeValue)||!d.hash().equals(hash))throw error(409,"IDEMPOTENCY_CONFLICT");String fp=fingerprint(event,registration,expected,c.id(),hash.value(),label);var old=previous(p,key,"CODE_REDEEM",event,registration,fp,at);if(!d.state().equals("ACTIVE")||d.generation()!=r.deviceGeneration())throw error(409,"RACE_DEVICE_REVOKED");return new LifecycleService.Outcome<>(JSON.readValue(old.resultJson(),RedemptionReceipt.class),null);}
   // No valid own receipt: any live shared namespace occupant is conflicting, before business checks.
   ledger.replay(p.accountId(),key,"RACE_CODE_REDEEM","[]",at);
   var e=lifecycle.reconcile(locked.event(),at,true,"API_RECONCILIATION");
   var check=LifecycleService.validate(()->{version(expected,r);String state=EventLifecycle.effective(e.status(),e.scheduledStartAt(),e.endAt(),at);if(state.equals("ENDED"))throw error(409,"RACE_ENDED");if(!state.equals("RUNNING"))throw error(409,"RACE_NOT_STARTED");var run=r.currentRunId()==null?null:store.run(registration,r.currentRunId(),true);if(r.currentRunId()!=null&&run==null)throw error(503,"RACE_STATE_UNAVAILABLE");Code found=store.availableCode(registration,codeValue);if(found==null)throw error(409,"START_CODE_INVALID");var c=store.code(registration,found.id(),true);if(c==null||!c.state().equals("AVAILABLE"))throw error(409,"START_CODE_INVALID");if(run==null&&!c.kind().equals("ORIGINAL"))throw error(409,"PARTICIPATION_NOT_STARTED");if(run!=null&&run.status().equals("COMPLETED"))throw error(409,"RUN_ALREADY_COMPLETED");if(store.deviceHashExists(hash))throw error(409,"DEVICE_SECRET_REUSED");return new Planned(c,run);});
   if(check.failure()!=null)return new LifecycleService.Outcome<RedemptionReceipt>(null,check.failure());var c=check.value().code();Run run=check.value().run();boolean first=run==null;long generation=first?1:Math.addExact(r.deviceGeneration(),1);long updated=Math.addExact(expected,1);long points=first||c.kind().equals("ORIGINAL")?0:c.points();UUID device=UUID.randomUUID(),command=UUID.randomUUID();
   if(first){var stages=events.stages(event);var definition=new RaceEvaluator.Definition(e.skipPenaltyPoints(),e.defaultWrongCodePenaltyPoints(),stages.stream().map(v->{var st=v.data();return new RaceEvaluator.Stage(st.id(),v.sourceTemplateStageId(),st.sequenceNo(),st.name(),st.expectedDurationMs(),st.maxPenaltyPoints(),st.instructionsMarkdown(),st.configuration());}).toList());if(stages.isEmpty())throw error(503,"RACE_STATE_UNAVAILABLE");var initial=evaluator.start(definition,at);run=new Run(UUID.randomUUID(),registration,event,1,"RUNNING",1,at,null,null,0);store.insertRun(run);for(int i=0;i<initial.stages().size();i++){var progress=initial.stages().get(i);store.insertProgress(new Progress(run.id(),event,progress.stageId(),stages.get(i).data().sequenceNo(),progress.status(),progress.activatedAt(),progress.completedAt(),progress.endedAt(),progress.codeSatisfied(),progress.gpsSatisfied()));}if(!store.bindInitialRun(registration,expected,run.id(),p.accountId(),at))throw error(409,"REGISTRATION_VERSION_CONFLICT");}
   else{BigInteger total=BigInteger.ZERO;for(var adjustment:store.adjustments(registration))total=total.add(BigInteger.valueOf(adjustment.points()));total.add(BigInteger.valueOf(points)).longValueExact();var current=store.currentDevice(registration,true);if(current!=null&&!store.revokeDevice(registration,current.id(),current.generation(),at,p.accountId(),"TAKEOVER"))throw error(503,"RACE_STATE_UNAVAILABLE");if(!store.advanceDeviceGeneration(registration,expected,r.deviceGeneration(),at))throw error(409,"REGISTRATION_VERSION_CONFLICT");}
   store.insertDevice(new Device(device,registration,generation,hash,"ACTIVE",at,null,c.id(),label,null,null));if(!store.consumeCode(registration,c.id(),c.version(),device,at))throw error(409,"START_CODE_INVALID");long runVersion=run.version();if(points!=0){store.insertAdjustment(new Adjustment(UUID.randomUUID(),registration,c.id(),points,at,c.reason()));if(!store.touchRun(registration,run.id(),runVersion))throw error(409,"RACE_VERSION_CONFLICT");runVersion=Math.addExact(runVersion,1);}
   var receipt=new RedemptionReceipt(registration,updated,c.id(),c.kind(),first?"START":"TAKEOVER",first?at:r.startedAt(),run.id(),run.activationGeneration(),runVersion,device,generation,Long.toString(points));String fp=fingerprint(event,registration,expected,c.id(),hash.value(),label);evidence(p,key,event,registration,"CODE_REDEEM",fp,c.id(),device,command,at,receipt);
   if(first)audit.raceDevice(p.accountId(),AuditService.Event.CREW_INDIVIDUALLY_STARTED,registration,JSON.writeValueAsString(receipt));audit.raceDevice(p.accountId(),first?AuditService.Event.RACE_DEVICE_AUTHORIZED:AuditService.Event.RACE_DEVICE_TAKEN_OVER,registration,JSON.writeValueAsString(receipt));return new LifecycleService.Outcome<>(receipt,null);
  });return outcome.get();}catch(org.springframework.dao.DataAccessException|IllegalStateException|ArithmeticException failure){throw new AuthFailure(503,"RACE_STATE_UNAVAILABLE",failure);}
 }
 public RevocationReceipt revoke(Principal p,UUID event,UUID registration,UUID device,UUID key,long expected,long generation,String rawReason){if(key==null||expected<0||generation<1)throw error(400,"INVALID_REQUEST");String reason=text(rawReason,2000);
  try{return tx.execute(s->{var locked=lock(p,event,registration,true);var r=locked.registration();Instant at=now();String fp=fingerprint(event,registration,device,expected,generation,reason==null?null:hashes.hash(reason));var old=previous(p,key,"DEVICE_REVOKE",event,registration,fp,at);if(old!=null)return JSON.readValue(old.resultJson(),RevocationReceipt.class);version(expected,r);if(r.currentRunId()!=null)store.run(registration,r.currentRunId(),true);var d=store.device(registration,device,true);if(d==null)throw error(404,"RACE_DEVICE_NOT_FOUND");if(!d.state().equals("ACTIVE"))throw error(409,"DEVICE_ALREADY_REVOKED");if(d.generation()!=generation||generation!=r.deviceGeneration())throw error(409,"DEVICE_GENERATION_CONFLICT");if(r.currentRunId()==null)throw error(503,"RACE_STATE_UNAVAILABLE");if(!store.revokeDevice(registration,device,generation,at,p.accountId(),reason)||!store.advanceDeviceGeneration(registration,expected,generation,at))throw error(409,"REGISTRATION_VERSION_CONFLICT");UUID command=UUID.randomUUID();var receipt=new RevocationReceipt(command,registration,Math.addExact(expected,1),device,generation,Math.addExact(generation,1),"REVOKED",at,r.currentRunId());evidence(p,key,event,registration,"DEVICE_REVOKE",fp,null,device,command,at,receipt);audit.raceDevice(p.accountId(),AuditService.Event.RACE_DEVICE_REVOKED,registration,JSON.writeValueAsString(receipt));return receipt;});}catch(org.springframework.dao.DataAccessException|IllegalStateException|ArithmeticException failure){throw new AuthFailure(503,"RACE_STATE_UNAVAILABLE",failure);}
 }
 public StartStatus status(Principal p,UUID event,UUID registration){var read=new TransactionTemplate(tx.getTransactionManager());read.setReadOnly(true);read.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return read.execute(s->{authorize(p,false,false);UUID crew=registrations.crew(event,registration);var c=crew==null?null:crews.read(crew);if(c==null||!p.accountId().equals(c.captainAccountId())&&!roles.administrator(p.accountId()))throw error(404,"REGISTRATION_NOT_FOUND");var e=events.read(event);if(e==null)throw error(404,"RACE_EVENT_NOT_FOUND");var r=store.registration(registration,false);if(r==null||!r.eventId().equals(event))throw error(404,"REGISTRATION_NOT_FOUND");Instant at=now();String state=EventLifecycle.effective(e.status(),e.scheduledStartAt(),e.endAt(),at);boolean owner=p.accountId().equals(c.captainAccountId());var run=r.currentRunId()==null?null:store.run(registration,r.currentRunId(),false);String time=state.equals("ENDED")?"RACE_ENDED":!state.equals("RUNNING")?"RACE_NOT_STARTED":null;String start=!owner?"NOT_CAPTAIN":r.currentRunId()!=null?"PARTICIPATION_ALREADY_STARTED":time;String takeover=!owner?"NOT_CAPTAIN":run==null?"PARTICIPATION_NOT_STARTED":run.status().equals("COMPLETED")?"RUN_ALREADY_COMPLETED":time;var d=store.currentDevice(registration,false);return new StartStatus(registration,r.version(),at,state,r.startedAt(),start==null,start,r.currentRunId(),takeover==null,takeover,r.deviceGeneration(),d==null?null:new ActiveDevice(d.id(),d.generation(),d.createdAt(),d.label()));});}
}
